#rf-root,.hf-root{--x3:#574953;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-pushout 0.5s cubic-bezier(.76,0,.24,1) 5s both;}.cam{position:absolute;inset:0;animation:st-cam 5.5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.sc-msg{max-width:78%;padding:20px 26px;border-radius:28px;font-size:30px;line-height:1.3;margin:16px 0;font-weight:500}.sc-msg.in{background:color-mix(in srgb,var(--rf-text) 12%,transparent);border-bottom-left-radius:8px;transform-origin:left}.sc-msg.out{margin-left:auto;background:var(--rf-accent);color:var(--rf-bg);border-bottom-right-radius:8px;transform-origin:right}.ph-hd{position:absolute;left:90px;right:90px;top:250px;text-align:center;font-size:84px;font-weight:var(--rf-heading-weight);letter-spacing:-.035em;line-height:1}
.ph{position:absolute;left:50%;top:520px;width:560px;height:1140px;margin-left:-280px;border-radius:84px;padding:18px;background:color-mix(in srgb,var(--rf-text) 16%,var(--rf-surface));box-shadow:0 40px 80px -40px rgba(0,0,0,.6),0 0 0 3px color-mix(in srgb,var(--rf-text) 14%,transparent);animation:ph-in 1.2s cubic-bezier(.16,1,.3,1) 0.1s both}
@keyframes ph-in{from{transform:translateY(240px);opacity:0}}
.ph-in{position:relative;height:100%;border-radius:68px;overflow:hidden;background:var(--rf-bg);padding:90px 40px 40px;color:var(--rf-text)}
.ph-notch{position:absolute;top:22px;left:50%;width:150px;height:40px;margin-left:-75px;border-radius:30px;background:#000}
.sc-h{font-size:28px;font-weight:600;color:var(--rf-muted)}
.sc-k{font-size:28px;color:var(--rf-muted);margin-top:20px}
.sc-big{font-size:76px;font-weight:600;letter-spacing:-.03em;line-height:1.05}
.sc-row{display:flex;align-items:center;gap:20px;font-size:30px;font-weight:600;padding:24px 0;border-bottom:2px solid color-mix(in srgb,var(--rf-text) 8%,transparent)}
.sc-row b{margin-left:auto;font-family:"JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;font-size:26px}
.sc-dot{width:22px;height:22px;border-radius:50%}
.chip{position:absolute;display:flex;align-items:center;gap:16px;padding:22px 30px;border-radius:26px;font-size:34px;font-weight:600;color:var(--rf-text);background:var(--rf-surface);border:2px solid color-mix(in srgb,var(--rf-text) 10%,transparent);z-index:3}
.chip .ic{color:var(--rf-muted)}

